document.addEventListener('DOMContentLoaded', () => { const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('visible'); observer.unobserve(entry.target); } }); }, { threshold: 0.15, rootMargin: '0px 0px -50px 0px' }); document.querySelectorAll('.animate-on-scroll').forEach(el => observer.observe(el)); const contadores = document.querySelectorAll('.contador__item strong'); const contadorObserver = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { const el = entry.target; const texto = el.textContent.trim(); const numero = parseInt(texto.replace(/[^0-9]/g, '')); const prefijo = texto.match(/^[^0-9]*/)[0]; const sufijo = texto.match(/[^0-9]*$/)[0]; if (isNaN(numero)) return; let actual = 0; const duracion = 2000; const pasos = 60; const incremento = numero / pasos; const intervalo = duracion / pasos; el.classList.add('contando'); const timer = setInterval(() => { actual += incremento; if (actual >= numero) { actual = numero; clearInterval(timer); el.classList.remove('contando'); } el.textContent = prefijo + Math.floor(actual) + sufijo; }, intervalo); contadorObserver.unobserve(el); } }); }, { threshold: 0.5 }); contadores.forEach(c => contadorObserver.observe(c)); const typewriter = document.querySelector('.typewriter-text'); if (typewriter) { setTimeout(() => { typewriter.classList.add('finished'); }, 4000); } const heroBg = document.querySelector('.hero__bg'); if (heroBg) { window.addEventListener('scroll', () => { const scrolled = window.pageYOffset; if (scrolled < window.innerHeight) { heroBg.style.transform = `translateY(${scrolled * 0.4}px)`; } }, { passive: true }); } const cursor = document.querySelector('.cursor-dorado'); if (cursor && window.matchMedia('(min-width: 969px)').matches) { let mouseX = 0, mouseY = 0; let cursorX = 0, cursorY = 0; document.addEventListener('mousemove', (e) => { mouseX = e.clientX; mouseY = e.clientY; }); const animarCursor = () => { cursorX += (mouseX - cursorX) * 0.15; cursorY += (mouseY - cursorY) * 0.15; cursor.style.left = cursorX + 'px'; cursor.style.top = cursorY + 'px'; requestAnimationFrame(animarCursor); }; animarCursor(); document.querySelectorAll('a, button, .servicio, .trabajo, .galeria__item').forEach(el => { el.addEventListener('mouseenter', () => cursor.classList.add('hover')); el.addEventListener('mouseleave', () => cursor.classList.remove('hover')); }); } const header = document.querySelector('.header'); if (header) { window.addEventListener('scroll', () => { if (window.pageYOffset > 100) { header.style.backgroundColor = 'rgba(10, 31, 51, 0.98)'; header.style.boxShadow = '0 10px 30px rgba(0, 0, 0, 0.3)'; } else { header.style.backgroundColor = 'rgba(10, 31, 51, 0.85)'; header.style.boxShadow = 'none'; } }, { passive: true }); } }); const loader = document.getElementById('loader'); if (loader) { window.addEventListener('load', () => { setTimeout(() => { loader.classList.add('hidden'); }, 800); }); } const volverArriba = document.getElementById('volverArriba'); if (volverArriba) { window.addEventListener('scroll', () => { if (window.pageYOffset > 500) { volverArriba.classList.add('visible'); } else { volverArriba.classList.remove('visible'); } }, { passive: true }); volverArriba.addEventListener('click', (e) => { e.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); }); } document.querySelectorAll('.comparador').forEach(comparador => { const input = comparador.querySelector('.comparador__input'); const antes = comparador.querySelector('.comparador__antes'); const slider = comparador.querySelector('.comparador__slider'); if (input && antes && slider) { const actualizar = () => { const valor = input.value; antes.style.width = valor + '%'; slider.style.left = valor + '%'; }; input.addEventListener('input', actualizar); actualizar(); } }); document.addEventListener('DOMContentLoaded', function() { const slides = document.querySelectorAll('.slider-full__slide'); const dots = document.querySelectorAll('.slider-full__dot'); const prevBtn = document.querySelector('.slider-full__arrow--prev'); const nextBtn = document.querySelector('.slider-full__arrow--next'); if (slides.length === 0) return; let currentSlide = 0; let autoPlayInterval = null; const DURACION_SLIDE = 5000; function showSlide(index) { slides.forEach(s => s.classList.remove('slider-full__slide--active')); dots.forEach(d => d.classList.remove('slider-full__dot--active')); slides[index].classList.add('slider-full__slide--active'); if (dots[index]) { dots[index].classList.add('slider-full__dot--active'); } currentSlide = index; } function nextSlide() { const next = (currentSlide + 1) % slides.length; showSlide(next); } function prevSlide() { const prev = (currentSlide - 1 + slides.length) % slides.length; showSlide(prev); } function iniciarAutoPlay() { autoPlayInterval = setInterval(nextSlide, DURACION_SLIDE); } function reiniciarAutoPlay() { clearInterval(autoPlayInterval); iniciarAutoPlay(); } dots.forEach((dot, index) => { dot.addEventListener('click', function() { showSlide(index); reiniciarAutoPlay(); }); }); if (prevBtn) { prevBtn.addEventListener('click', function() { prevSlide(); reiniciarAutoPlay(); }); } if (nextBtn) { nextBtn.addEventListener('click', function() { nextSlide(); reiniciarAutoPlay(); }); } const sliderContainer = document.querySelector('.slider-full'); if (sliderContainer) { sliderContainer.addEventListener('mouseenter', () => { clearInterval(autoPlayInterval); }); sliderContainer.addEventListener('mouseleave', () => { iniciarAutoPlay(); }); } document.addEventListener('keydown', function(e) { if (e.key === 'ArrowRight') { nextSlide(); reiniciarAutoPlay(); } else if (e.key === 'ArrowLeft') { prevSlide(); reiniciarAutoPlay(); } }); iniciarAutoPlay(); }); const calcServicio = document.getElementById('calcServicio'); const calcMetros = document.getElementById('calcMetros'); const calcMetrosValor = document.getElementById('calcMetrosValor'); const calcFrecuencia = document.getElementById('calcFrecuencia'); const calcExtCristales = document.getElementById('calcExtCristales'); const calcExtProfunda = document.getElementById('calcExtProfunda'); const calcExtEco = document.getElementById('calcExtEco'); const calcResultado = document.getElementById('calcResultado'); if (calcServicio && calcResultado) { const calcular = () => { const servicio = parseFloat(calcServicio.value); const metros = parseInt(calcMetros.value); const frecuencia = parseFloat(calcFrecuencia.value); let precio = metros * 0.5 * servicio * frecuencia; if (calcExtCristales.checked) precio += parseFloat(calcExtCristales.value); if (calcExtProfunda.checked) precio += parseFloat(calcExtProfunda.value); if (calcExtEco.checked) precio += parseFloat(calcExtEco.value); precio = Math.max(49, Math.round(precio)); calcResultado.textContent = precio + '€'; }; calcMetros.addEventListener('input', () => { calcMetrosValor.textContent = calcMetros.value + ' m²'; calcular(); }); [calcServicio, calcFrecuencia, calcExtCristales, calcExtProfunda, calcExtEco].forEach(el => { el.addEventListener('change', calcular); }); calcular(); } document.getElementById('activarSonido').addEventListener('click', () => { document.getElementById('sonidoWhoosh').play(); }); (function() { const anuncio = document.getElementById('anuncio'); if (!anuncio) return; if (sessionStorage.getItem('anuncioVisto') === 'true') { anuncio.style.display = 'none'; return; } const sonidoWhoosh = document.getElementById('sonidoWhoosh'); function reproducir(audio, volumen = 0.5) { if (!audio) return; try { audio.volume = volumen; audio.currentTime = 0; const playPromise = audio.play(); if (playPromise !== undefined) { playPromise.catch(() => { console.log('Autoplay bloqueado por el navegador'); }); } } catch (e) { } } setTimeout(() => reproducir(sonidoWhoosh, 0.1), 200); setTimeout(() => { anuncio.style.display = 'none'; sessionStorage.setItem('anuncioVisto', 'true'); }, 5000); anuncio.addEventListener('click', () => { anuncio.style.display = 'none'; sessionStorage.setItem('anuncioVisto', 'true'); }); })();